buildEscalationMessage(monitor: Monitor, clientHost: string): NotificationMessage {
		const content: NotificationContent = {
			title: `Escalation: ${monitor.name} Still Down`,
			summary: `Monitor "${monitor.name}" has been down for an extended period. This is an escalation notification.`,
			details: [
				`URL: ${monitor.url}`,
				`Status: Down`,
				`Type: ${monitor.type}`,
				`Please investigate immediately.`,
			],
			timestamp: new Date(),
		};

		return {
			type: "monitor_down",
			severity: "critical",
			monitor: {
				id: monitor.id,
				name: monitor.name,
				url: monitor.url,
				type: monitor.type,
				status: monitor.status,
			},
			content,
			clientHost,
			metadata: {
				teamId: monitor.teamId,
				notificationReason: "escalation",
			},
		};
	}

