export interface IEscalationService {
	checkAndSendEscalations(): Promise<void>;
}

export class EscalationService implements IEscalationService {
	static SERVICE_NAME = SERVICE_NAME;

	private logger: ILogger;
	private incidentsRepository: IIncidentsRepository;
	private monitorsRepository: IMonitorsRepository;
	private notificationsRepository: INotificationsRepository;
	private notificationService: INotificationsService;
	private notificationMessageBuilder: INotificationMessageBuilder;

	constructor(
		logger: ILogger,
		incidentsRepository: IIncidentsRepository,
		monitorsRepository: IMonitorsRepository,
		notificationsRepository: INotificationsRepository,
		notificationService: INotificationsService,
		notificationMessageBuilder: INotificationMessageBuilder
	) {
		this.logger = logger;
		this.incidentsRepository = incidentsRepository;
		this.monitorsRepository = monitorsRepository;
		this.notificationsRepository = notificationsRepository;
		this.notificationService = notificationService;
		this.notificationMessageBuilder = notificationMessageBuilder;
	}

	get serviceName() {
		return EscalationService.SERVICE_NAME;
	}

	checkAndSendEscalations = async (): Promise<void> => {
		try {
			// Get all active incidents without escalation
			const activeIncidents = await this.incidentsRepository.findByFilter({
				status: true,
				escalationLevel: 0,
			} as any);

			if (!activeIncidents || activeIncidents.length === 0) {
				return;
			}

			const now = new Date();

			for (const incident of activeIncidents) {
				try {
					const monitor = await this.monitorsRepository.getById(incident.monitorId, incident.teamId);

					if (!monitor || !monitor.escalationEnabled) {
						continue;
					}

					const startTime = new Date(incident.startTime);
					const escalationTime = new Date(startTime.getTime() + monitor.escalationDelayMinutes! * 60 * 1000);

					// Check if it's time to escalate
					if (now >= escalationTime) {
						await this.sendEscalationNotification(monitor, incident);

						// Mark incident as escalated
						incident.escalationLevel = 1;
						incident.escalationTriggeredAt = new Date(now.toISOString());
						await this.incidentsRepository.updateById(incident.id, incident.teamId, incident);

						this.logger.debug(`Escalation sent for incident ${incident.id} on monitor ${monitor.id}`);
					}
				} catch (error) {
					this.logger.error(`Error processing escalation for incident ${incident.id}:`, error);
					// Continue with next incident
				}
			}
		} catch (error) {
			this.logger.error("Error in checkAndSendEscalations:", error);
		}
	};

	private sendEscalationNotification = async (monitor: Monitor, incident: Incident): Promise<void> => {
		if (!monitor.escalationNotificationIds || monitor.escalationNotificationIds.length === 0) {
			this.logger.warn(`No escalation notification IDs configured for monitor ${monitor.id}`);
			return;
		}

		try {
			// Build escalation message with default client host
			const clientHost = "localhost"; // This could be passed via settings service
			const message = this.notificationMessageBuilder.buildEscalationMessage(monitor, clientHost);

			// Send to each escalation notification channel
			const tasks = [];
			for (const notificationId of monitor.escalationNotificationIds) {
				try {
					const notification = await this.notificationsRepository.getById(notificationId, monitor.teamId);
					if (notification) {
						tasks.push(this.notificationService.sendEscalationNotification(notification, message));
					}
				} catch (error) {
					this.logger.warn(`Failed to fetch notification ${notificationId}:`, error);
				}
			}

			// Send all notifications in parallel
			if (tasks.length > 0) {
				const outcomes = await Promise.all(tasks);
				const succeeded = outcomes.filter(Boolean).length;
				const failed = outcomes.length - succeeded;

				if (failed > 0) {
					this.logger.warn(`Escalation notification send completed with ${succeeded} success, ${failed} failure(s)`);

