			// Process each team
			for (const teamId of teamIds) {
				try {
					// Get all active incidents for this team
					const incidents = await this.incidentsRepository.findByTeamId(teamId, escalationCheckStartDate, 1, 1000, undefined, true);

					for (const incident of incidents) {
						try {
							// Skip if already escalated
							if (incident.escalationLevel && incident.escalationLevel > 0) {
								continue;
							}

							// Skip if escalation not enabled for this monitor
							const monitor = await this.monitorsRepository.findById(incident.monitorId, teamId);
							if (!monitor.escalationEnabled || !monitor.escalationDelayMinutes) {
								continue;
							}

							// Calculate if escalation threshold has been met
							const incidentStartTime = new Date(incident.createdAt);
							const escalationTime = new Date(incidentStartTime.getTime() + monitor.escalationDelayMinutes * 60 * 1000);

							if (now >= escalationTime) {
								// Send escalation notification
								await this.sendEscalationNotification(monitor, incident, this.envConfig.clientHost);

								// Update incident to mark as escalated
								await this.incidentsRepository.updateById(incident.id, teamId, {
									escalationLevel: 1,
									escalationTriggeredAt: now,
								} as any);

								this.logger.info({
									service: SERVICE_NAME,
									method: "checkAndSendEscalations",
									message: `Sent escalation notification for incident`,
									details: {
										incidentId: incident.id,
										monitorId: monitor.id,
										monitorName: monitor.name,
										delayMinutes: monitor.escalationDelayMinutes,
									},
								});
							}
						} catch (incidentError) {
							this.logger.warn({
								service: SERVICE_NAME,
								method: "checkAndSendEscalations",
								message: `Error processing incident for escalation`,
								details: { incidentId: incident.id },
								stack: incidentError instanceof Error ? incidentError.stack : undefined,
							});
						}
					}
				} catch (teamError) {
					this.logger.warn({
						service: SERVICE_NAME,
						method: "checkAndSendEscalations",
						message: `Error processing team for escalation`,
						details: { teamId },
						stack: teamError instanceof Error ? teamError.stack : undefined,
					});
				}
			}

			this.logger.debug({
				service: SERVICE_NAME,
				method: "checkAndSendEscalations",
				message: "Escalation check completed",
			})

